/*
 * Matter-Rust: all UI, DOM, CSS, sound and interactions generated by JS.
 * No tracking, no tokens, no live connector or Vault operations.
 * Créditos:
 * Hecho por Lournyx Matterssmith [Lou-Nyx].
 */
(() => {
  'use strict';

  const CSS = "\n:root{--bg:#070b18;--glass:rgba(16,23,44,.79);--tile:#101a33;--line:rgba(98,217,255,.21);--txt:#e9f7ff;--muted:#91a8c5;--a:#58deff;--b:#9e77ff;--glow:rgba(63,210,255,.2);font-family:Inter,\"Segoe UI\",system-ui,sans-serif;color-scheme:dark}\n:root[data-theme=\"violet\"]{--a:#d092ff;--b:#ff79cd;--glow:rgba(212,117,255,.2)}\n:root[data-theme=\"amber\"]{--a:#ffcb70;--b:#ff7b5d;--glow:rgba(255,181,77,.18)}\n:root[data-theme=\"jade\"]{--a:#64ffc8;--b:#5be4e3;--glow:rgba(43,255,174,.17)}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 80% 1%,var(--glow),transparent 35%),radial-gradient(ellipse at 10% 40%,rgba(85,65,170,.14),transparent 38%),var(--bg);color:var(--txt)}button,input,select{font:inherit}button{cursor:pointer}\nbutton:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--a);outline-offset:3px}\n#matter-app{min-height:100vh;position:relative;overflow:hidden}\n.stars{position:fixed;pointer-events:none;inset:0;z-index:0;opacity:.26;background-image:radial-gradient(1px 1px at 15% 15%,white 99%,transparent),radial-gradient(1px 1px at 90% 20%,white 99%,transparent),radial-gradient(1px 1px at 44% 74%,white 99%,transparent),radial-gradient(2px 2px at 60% 40%,white 99%,transparent);background-size:200px 240px;animation:drift 32s linear infinite}\n@keyframes drift{to{transform:translateY(-240px)}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}html{scroll-behavior:auto}}\n.shell{position:relative;z-index:1;max-width:1320px;margin:0 auto;padding:24px clamp(14px,3vw,42px) 48px}\n.top{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap;padding-bottom:16px;border-bottom:1px solid var(--line)}\n.brand{display:flex;align-items:center;gap:14px}.logo{width:46px;height:46px;display:grid;place-items:center;font-size:26px;font-weight:900;color:var(--bg);background:linear-gradient(130deg,var(--a),var(--b));border-radius:15px;box-shadow:0 0 26px var(--glow)}\n.eyebrow{text-transform:uppercase;letter-spacing:.16em;color:var(--a);font-size:11px;font-weight:800}.brand h1{font-size:22px;line-height:1.05;margin:3px 0}\n.mini{font-size:12px;color:var(--muted)}.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.pill,button.pill{padding:9px 13px;border:1px solid var(--line);border-radius:12px;color:var(--txt);background:var(--glass);transition:transform .18s,border-color .18s}\n.pill:hover{transform:translateY(-2px);border-color:var(--a)}.primary{border:none!important;background:linear-gradient(120deg,var(--a),var(--b))!important;color:#06101f!important;font-weight:800}\n.hero{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(220px,.75fr);gap:22px;margin:38px 0 26px;align-items:center}\n.hero h2{font-size:clamp(32px,5.2vw,66px);letter-spacing:-.055em;line-height:1.04;margin:12px 0 18px}\n.hero .accent{background:linear-gradient(95deg,var(--a),var(--b));-webkit-background-clip:text;background-clip:text;color:transparent}\n.hero p{max-width:650px;color:var(--muted);line-height:1.7;font-size:15px;margin:0}\n.orb-wrap{display:grid;place-items:center;min-height:210px}.orb{display:grid;place-items:center;width:min(230px,40vw);aspect-ratio:1;border:1px solid var(--line);border-radius:35%;background:radial-gradient(circle,var(--glow),transparent 65%);box-shadow:0 0 90px var(--glow),inset 0 0 55px var(--glow);font-size:clamp(50px,8vw,94px);transform:rotate(-9deg);animation:float 6s ease-in-out infinite}\n@keyframes float{50%{transform:translateY(-10px) rotate(8deg)}}\n.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:25px 0}\n.stat{border:1px solid var(--line);background:var(--glass);backdrop-filter:blur(16px);border-radius:18px;padding:20px}.num{display:block;font-size:clamp(23px,3vw,34px);color:var(--a);font-weight:800;letter-spacing:-.05em}\n.caption{font-size:12px;color:var(--muted)}\n.section-head{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin:24px 0 13px}.section-head h3{font-size:22px;margin:0}.section-head small{color:var(--muted)}\n.toolbar{display:grid;grid-template-columns:minmax(170px,2fr) minmax(100px,1fr) minmax(110px,1fr);gap:10px;margin:15px 0}\n.field{border:1px solid var(--line);background:var(--glass);color:var(--txt);min-width:0;border-radius:12px;padding:13px 14px}.field::placeholder{color:#8299b4}\n.tabs{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.tab{border:1px solid var(--line);color:var(--muted);background:rgba(20,30,55,.68);padding:8px 12px;border-radius:10px}.tab[aria-pressed=\"true\"]{border-color:var(--a);color:var(--a);background:var(--glow)}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,270px),1fr));gap:12px}\n.tile{padding:16px;min-height:138px;background:var(--glass);border:1px solid var(--line);border-radius:17px;display:flex;flex-direction:column;gap:10px;text-align:left;color:inherit;transition:transform .15s,border-color .15s,box-shadow .15s}\n.tile:hover{transform:translateY(-3px);border-color:var(--a);box-shadow:0 8px 35px var(--glow)}.tile[aria-pressed=\"true\"]{border-color:var(--a);box-shadow:inset 0 0 0 1px var(--a)}\n.tile .title{font-size:15px;font-weight:750;line-height:1.35}.tile .sub{font-size:12px;color:var(--muted)}.tile .foot{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-top:auto}\n.tag{padding:4px 8px;border:1px solid var(--line);border-radius:8px;font-size:11px;color:var(--muted);background:#0c1429}\n.tag[data-status=\"offline\"]{color:#77f5bc;border-color:rgba(119,245,188,.38)}.tag[data-status=\"reference\"]{color:#92caff;border-color:rgba(146,202,255,.32)}.tag[data-status=\"unverified\"]{color:#ffd188;border-color:rgba(255,209,136,.35)}\n.detail{margin:18px 0;background:var(--glass);border:1px solid var(--line);padding:20px;border-radius:18px}.detail h3{margin:0 0 10px}.detail p{color:var(--muted);line-height:1.6}\n.refs{display:flex;flex-wrap:wrap;gap:8px}.refs a{color:var(--a);text-decoration:none;border:1px solid var(--line);border-radius:8px;padding:8px 11px;font-size:12px}\n.notice{padding:13px 16px;border:1px dashed var(--line);border-radius:12px;color:var(--muted);line-height:1.55;margin:14px 0}\nfooter{font-size:12px;color:var(--muted);border-top:1px solid var(--line);margin-top:30px;padding:20px 0;line-height:1.8}\n#diagnostics{white-space:pre-wrap;font-family:ui-monospace,Consolas,monospace;font-size:12px;color:var(--a);overflow-wrap:anywhere}\n.theme-dot{display:inline-block;width:9px;height:9px;border-radius:100%;margin-right:6px;background:var(--a)}.empty{grid-column:1/-1;padding:25px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:14px}\n@media(max-width:780px){.hero{grid-template-columns:1fr}.orb-wrap{display:none}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.toolbar{grid-template-columns:1fr 1fr}.toolbar input{grid-column:1/-1}.shell{padding:15px 14px 30px}.hero{margin:25px 0}.top{align-items:flex-start}}\n@media(max-width:420px){.actions{width:100%}.actions button{flex:1}.stats{gap:7px}.stat{padding:14px 11px}.tile{min-height:122px}}\n";
  const style = document.createElement('style');
  style.textContent = CSS;
  document.head.appendChild(style);

  const app = document.createElement('main');
  app.id = 'matter-app';
  app.innerHTML =
    '<div class="stars" aria-hidden="true"></div>' +
    '<div class="shell">' +
      '<header class="top">' +
        '<div class="brand"><div class="logo" aria-hidden="true">✦</div><div>' +
          '<span class="eyebrow">꧁✪⃢.✪ Matterssmith ۞₪»̶⟩</span>' +
          '<h1>Matter-Rust</h1><span class="mini">Consola universal de capacidades · Rust</span>' +
        '</div></div>' +
        '<nav class="actions" aria-label="Controles de consola">' +
          '<button class="pill" id="theme-btn" type="button" title="Cambiar tema">◐ Tema</button>' +
          '<button class="pill" id="sound-btn" type="button" aria-pressed="false">♫ Audio: OFF</button>' +
          '<button class="pill" id="full-btn" type="button">⛶ Pantalla</button>' +
        '</nav>' +
      '</header>' +
      '<section class="hero"><div>' +
        '<span class="eyebrow">ENGINE / WHATSAPP · TELEGRAM · DISCORD · SOCIAL</span>' +
        '<h2>Un núcleo.<br><span class="accent">Todas las plataformas.</span></h2>' +
        '<p>Inventario verificable de funciones de WhatsMeow, Baileys y extensiones Matter. ' +
        'Las referencias oficiales no implican una función operativa en Matter-Rust. ' +
        'Esta consola es una vista local de pruebas: no conecta cuentas ni modifica Vault.</p>' +
      '</div><div class="orb-wrap" aria-hidden="true"><div class="orb">⌘</div></div></section>' +
      '<section class="stats" id="stats" aria-label="Indicadores del inventario"></section>' +
      '<section aria-label="Explorador de funciones">' +
        '<div class="section-head"><h3>Inventario de capacidades</h3><small id="result-count">Cargando…</small></div>' +
        '<div class="toolbar">' +
          '<input class="field" id="search" type="search" autocomplete="off" placeholder="Buscar mensajes, grupos, botones, Vault…" aria-label="Buscar capacidades" />' +
          '<select class="field" id="source" aria-label="Filtrar origen"><option value="">Todos los orígenes</option><option value="whatsmeow">WhatsMeow oficial</option><option value="baileys">Baileys oficial</option><option value="matter">Matter personalizado</option></select>' +
          '<select class="field" id="status" aria-label="Filtrar estado"><option value="">Todos los estados</option><option value="reference">Referencia oficial</option><option value="unverified">Sin prueba real</option><option value="offline">Contrato local</option><option value="planned">Pendiente</option></select>' +
        '</div><div id="tabs" class="tabs" role="group" aria-label="Categorías"></div>' +
        '<div id="cards" class="grid" aria-live="polite"></div>' +
        '<div id="detail" class="detail" hidden></div>' +
      '</section>' +
      '<section class="section-head"><h3>Herramientas de verificación</h3></section>' +
      '<div class="actions">' +
        '<button class="pill primary" type="button" id="check-btn">✓ Comprobar catálogo</button>' +
        '<button class="pill" type="button" id="export-btn">↓ Exportar JSON</button>' +
        '<button class="pill" type="button" id="copy-btn">⧉ Copiar resumen</button>' +
      '</div>' +
      '<div class="notice" role="note">Esta consola únicamente consulta inventario público y ejecuta verificaciones locales. No solicita contraseñas, pairing, documentos, fotos, permisos ni datos biométricos. El backend de registro e identidad está deshabilitado.</div>' +
      '<p id="diagnostics" role="status" aria-live="polite"></p>' +
      '<footer>Créditos: <strong>Hecho por Lournyx Matterssmith [Lou-Nyx].</strong> · Base-Matter / WhatsApp-Matter / Vault-Matter · Pantalla generada íntegramente en JavaScript. <span id="edition"></span></footer>' +
    '</div>';
  document.body.appendChild(app);

  const el = id => document.getElementById(id);
  const state = { catalog: null, query: '', source: '', status: '', category: '', theme: 0, audio: false, selected: '' };
  const themes = ['cyan','violet','amber','jade'];
  const statusText = {reference:'Referencia oficial',unverified:'Sin prueba real',offline:'Contrato local',planned:'Pendiente'};
  const make = (tag, className, value) => {
    const item = document.createElement(tag);
    if (className) item.className = className;
    if (value !== undefined) item.textContent = String(value);
    return item;
  };

  function chirp() {
    if (!state.audio) return;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(480, ctx.currentTime);
    o.frequency.exponentialRampToValueAtTime(740, ctx.currentTime + .08);
    g.gain.setValueAtTime(.025, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + .12);
    o.connect(g);
    g.connect(ctx.destination);
    o.start();
    o.stop(ctx.currentTime + .14);
    o.onended = () => { void ctx.close(); };
  }

  function stats() {
    const holder = el('stats');
    holder.replaceChildren();
    const data = state.catalog.capabilities;
    const values = [
      [data.length,'Capacidades catalogadas'],
      [new Set(data.map(x => x.group)).size,'Áreas funcionales'],
      [data.filter(x => x.status === 'offline').length,'Contratos / UI locales'],
      [data.filter(x => x.status === 'planned' || x.status === 'unverified').length,'Pendientes o sin prueba']
    ];
    values.forEach(([num, caption]) => {
      const block = make('div','stat');
      block.append(make('strong','num',num),make('span','caption',caption));
      holder.appendChild(block);
    });
  }

  function filtered() {
    if (!state.catalog) return [];
    const query = state.query.normalize('NFKD').toLocaleLowerCase('es').trim();
    return state.catalog.capabilities.filter(cap => {
      if (state.status && cap.status !== state.status) return false;
      if (state.category && cap.group !== state.category) return false;
      if (state.source && !cap.sources.some(s => s.project === state.source)) return false;
      if (!query) return true;
      const haystack = (cap.name + ' ' + cap.id + ' ' + cap.category + ' ' +
        cap.sources.map(s => s.project).join(' ')).normalize('NFKD').toLocaleLowerCase('es');
      return haystack.includes(query);
    });
  }

  function showDetail(cap) {
    state.selected = cap.id;
    const detail = el('detail');
    detail.replaceChildren();
    detail.hidden = false;
    detail.append(make('h3','',cap.name),make('span','tag',statusText[cap.status] || 'No verificado'));
    detail.appendChild(make('p','',cap.id + ' · ' + cap.category));
    detail.appendChild(make('p','',state.catalog.state_definitions[cap.status] || 'Sin evidencia'));
    const links = make('div','refs');
    cap.sources.forEach(ref => {
      if (typeof ref.url !== 'string' || !ref.url.startsWith('https://github.com/')) return;
      const link = make('a','',ref.project + ' · fuente');
      link.href = ref.url;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      links.appendChild(link);
    });
    detail.appendChild(links);
    detail.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});
    chirp();
  }

  function tabs() {
    const holder = el('tabs');
    holder.replaceChildren();
    const defs = [['','Todas']].concat([...new Map(state.catalog.capabilities.map(c => [c.group,c.category])).entries()]);
    defs.forEach(([id,name]) => {
      const tab = make('button','tab',name);
      tab.type = 'button';
      tab.setAttribute('aria-pressed',String(state.category === id));
      tab.addEventListener('click',() => {state.category=id;render();chirp();});
      holder.appendChild(tab);
    });
  }

  function render() {
    if (!state.catalog) return;
    tabs();
    const list = filtered();
    const holder = el('cards');
    holder.replaceChildren();
    el('result-count').textContent = list.length + ' de ' + state.catalog.capabilities.length + ' resultados';
    if (!list.length) holder.appendChild(make('p','empty','Sin coincidencias. Cambia los filtros.'));
    list.forEach(cap => {
      const tile = make('button','tile');
      tile.type = 'button';
      tile.setAttribute('aria-pressed', String(state.selected === cap.id));
      tile.append(
        make('div','mini',cap.category),
        make('div','title',cap.name),
        make('div','sub',cap.sources.map(x => x.project).join(' / ')),
      );
      const footer = make('div','foot');
      const badge = make('span','tag',statusText[cap.status] || 'Sin validar');
      badge.dataset.status = cap.status;
      footer.append(badge,make('span','mini','Ver ficha ›'));
      tile.appendChild(footer);
      tile.addEventListener('click',() => {showDetail(cap);renderCardsSelection();});
      holder.appendChild(tile);
    });
  }

  function renderCardsSelection() {
    el('cards').querySelectorAll('button.tile').forEach((button,index)=>{
      const filteredItems = filtered();
      button.setAttribute('aria-pressed',String(filteredItems[index] && filteredItems[index].id === state.selected));
    });
  }

  function diagnostics() {
    const c = state.catalog;
    if (!c) return;
    const items=c.capabilities;
    const ids=new Set(items.map(x=>x.id));
    const valid = items.length===ids.size &&
      items.every(x=>typeof x.name==='string' && x.name.length>0 &&
        Object.hasOwn(statusText,x.status) &&
        Array.isArray(x.sources) && x.sources.length>0 &&
        x.sources.every(s=>typeof s.url==='string' && s.url.startsWith('https://github.com/')));
    const points=[
      '[Matter-Rust] Autoprueba local de catálogo',
      'Datos: '+items.length+' capacidades / '+ids.size+' identificadores únicos',
      'Estados y fuentes válidos: '+(valid?'OK':'ERROR'),
      'HTML contiene solo arranque JS: comprobar en código fuente',
      'Conexiones de WhatsApp/Telegram/Discord: NO PROBADAS aquí',
      'Identidad, Vault y permisos: NO PROBADOS aquí',
      'Resultado: '+(valid?'INVENTARIO LOCAL VÁLIDO':'FALLÓ INVENTARIO')
    ];
    el('diagnostics').textContent=points.join('\n');
    chirp();
  }

  async function load() {
    try {
      const response=await fetch('./api/catalog',{cache:'no-store',credentials:'same-origin'});
      if(!response.ok) throw new Error('HTTP '+response.status);
      const catalog=await response.json();
      if(!catalog || catalog.schema_version!==1 || !Array.isArray(catalog.capabilities)) throw new Error('Formato inválido');
      if(catalog.capabilities.length>5000) throw new Error('Inventario demasiado grande');
      state.catalog=catalog;
      el('edition').textContent=' · Edición '+catalog.edition;
      stats();
      render();
      el('diagnostics').textContent='Catálogo cargado. Selecciona una función para consultar su origen y estado real.';
    }catch(error){
      el('diagnostics').textContent='Error: no se puede cargar el inventario local. Inicia el servidor Rust de Matter-Rust. '+error.message;
      el('result-count').textContent='Sin conexión al catálogo';
    }
  }

  el('search').addEventListener('input',e=>{state.query=e.target.value;render();});
  el('source').addEventListener('change',e=>{state.source=e.target.value;render();});
  el('status').addEventListener('change',e=>{state.status=e.target.value;render();});
  el('theme-btn').addEventListener('click',()=>{
    state.theme=(state.theme+1)%themes.length;
    document.documentElement.dataset.theme=themes[state.theme];
    chirp();
  });
  el('sound-btn').addEventListener('click',()=>{
    state.audio=!state.audio;
    const btn=el('sound-btn');
    btn.textContent=state.audio?'♫ Audio: ON':'♫ Audio: OFF';
    btn.setAttribute('aria-pressed',String(state.audio));
    chirp();
  });
  el('full-btn').addEventListener('click',async()=>{
    try {
      if(document.fullscreenElement) await document.exitFullscreen();
      else if(document.documentElement.requestFullscreen) await document.documentElement.requestFullscreen();
      else el('diagnostics').textContent='Pantalla completa no admitida por este navegador.';
    } catch { el('diagnostics').textContent='Pantalla completa denegada por el navegador.'; }
    chirp();
  });
  el('check-btn').addEventListener('click',diagnostics);
  el('export-btn').addEventListener('click',()=>{
    if(!state.catalog)return;
    const blob=new Blob([JSON.stringify(state.catalog,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    const a=make('a');a.href=url;a.download='matter-rust-capabilities.json';
    a.click();
    setTimeout(()=>URL.revokeObjectURL(url),2500);
    chirp();
  });
  el('copy-btn').addEventListener('click',async()=>{
    if(!state.catalog)return;
    const summary='Matter-Rust | '+state.catalog.capabilities.length+
      ' capacidades | '+state.catalog.edition+
      '\nCréditos: Hecho por Lournyx Matterssmith [Lou-Nyx].';
    try{await navigator.clipboard.writeText(summary);el('diagnostics').textContent='Resumen copiado.';}
    catch{el('diagnostics').textContent=summary;}
    chirp();
  });
  void load();
})();
